function useReveal() {
  const ref = useRef(null);
  const [vis, setVis] = useState(false);
  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setVis(true); obs.disconnect(); } }, { threshold: 0.06 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);
  return [ref, vis];
}

function Reveal({ children, delay = 0, style = {} }) {
  const [ref, vis] = useReveal();
  return (
    <div ref={ref} style={{ opacity: vis?1:0, transform: vis?"translateY(0)":"translateY(22px)", transition:`opacity 0.75s ${delay}s ease, transform 0.75s ${delay}s ease`, ...style }}>
      {children}
    </div>
  );
}

function TrendBadge({ trend }) {
  const config = {
    up:     { label:"↑ Rising",   bg:"rgba(44,74,62,0.1)",  color:C.accent },
    stable: { label:"→ Stable",   bg:"rgba(107,107,101,0.1)", color:C.mid },
    down:   { label:"↓ Softening",bg:"rgba(139,58,58,0.1)", color:"#8B3A3A" },
  };
  const t = config[trend] || config.stable;
  return (
    <span style={{ fontFamily:sans, fontSize:"0.58rem", fontWeight:500, letterSpacing:"0.1em", textTransform:"uppercase", color:t.color, background:t.bg, padding:"0.25rem 0.6rem", borderRadius:99, display:"inline-block" }}>
      {t.label}
    </span>
  );
}

function StatCard({ label, value, note }) {
  return (
    <div style={{ background:C.warm, border:`1px solid ${C.rule}`, borderRadius:4, padding:"1.1rem 1rem", textAlign:"center" }}>
      <div style={{ fontFamily:serif, fontSize:"1.6rem", fontWeight:300, color:C.accent, lineHeight:1, marginBottom:"0.3rem" }}>{value}</div>
      <div style={{ fontFamily:sans, fontSize:"0.58rem", fontWeight:500, letterSpacing:"0.12em", textTransform:"uppercase", color:C.mid }}>{label}</div>
      {note && <div style={{ fontFamily:sans, fontSize:"0.6rem", color:C.light, marginTop:"0.25rem" }}>{note}</div>}
    </div>
  );
}

